create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table if not exists venues(id uuid primary key default gen_random_uuid(), code text unique not null, kind text not null check(kind in ('CEX','DEX')), enabled boolean not null default false, created_at timestamptz not null default now());
create table if not exists networks(id uuid primary key default gen_random_uuid(), name text unique not null, chain_id bigint unique, rpc_ref text, native_token text, explorer text, enabled boolean not null default false);
create table if not exists tokens(id uuid primary key default gen_random_uuid(), chain_id bigint, address text, symbol text not null, name text, decimals integer not null, coingecko_id text, is_stable boolean not null default false, is_wrapped boolean not null default false, unique(chain_id,address));
create table if not exists opportunities(id uuid primary key default gen_random_uuid(), symbol text not null, buy_venue text not null, sell_venue text not null, buy_network text, sell_network text, quantity numeric not null, gross_profit numeric not null, trading_fees numeric not null, gas_cost numeric not null, slippage_cost numeric not null, bridge_cost numeric not null default 0, settlement_cost numeric not null default 0, safety_reserve numeric not null, net_profit numeric not null, net_profit_pct numeric not null, capital_required numeric not null, capital_source text not null, status text not null, confidence numeric not null, quote_timestamp timestamptz not null, expires_at timestamptz not null, created_at timestamptz not null default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(), opportunity_id uuid references opportunities(id), venue text not null, symbol text not null, side text not null, external_id text, status text not null, requested_quantity numeric, filled_quantity numeric default 0, average_price numeric, fee numeric, correlation_id uuid not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists capital_accounts(id uuid primary key default gen_random_uuid(), name text unique not null, source text not null, available numeric not null default 0, reserved numeric not null default 0, target_equity numeric, updated_at timestamptz not null default now());
create table if not exists risk_events(id uuid primary key default gen_random_uuid(), level text not null, reason text not null, correlation_id uuid, created_at timestamptz not null default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, correlation_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists system_health(id uuid primary key default gen_random_uuid(), component text unique not null, status text not null, heartbeat_at timestamptz not null default now(), details jsonb not null default '{}');
create index if not exists opportunities_exec_idx on opportunities(status,net_profit desc,expires_at);
create index if not exists orders_corr_idx on orders(correlation_id);
alter table profiles enable row level security; alter table opportunities enable row level security; alter table orders enable row level security; alter table audit_logs enable row level security;
create policy "profile self" on profiles for select using (auth.uid()=id);
create policy "opportunities authenticated" on opportunities for select to authenticated using (true);
create policy "orders authenticated" on orders for select to authenticated using (true);
create policy "audit own" on audit_logs for select to authenticated using (actor_id=auth.uid());
